INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6307391, 934328, 127046, '<td valign="top">I''m not sure I''m being led anywhere. I feel that the lines are almost fighting. The red is opposing the building lines. Nice comp though, just not sure about the leading part.</td>', 'I''m not sure I''m being led anywhere. I feel that the lines are almost fighting. The red is opposing the building lines. Nice comp though, just not sure about the leading part.', '2011-02-09 00:13:44.000000', NULL, 1),
(6307394, 934190, 15711, '<td valign="top">This has a certain sadness about it.  I like it.</td>', 'This has a certain sadness about it.  I like it.', '2011-02-09 00:14:31.000000', NULL, 1),
(6307399, 934039, 127046, '<td valign="top">This looks a bit more processed than is allowed according to the challenge rules. The arches make for an interesting comp though.</td>', 'This looks a bit more processed than is allowed according to the challenge rules. The arches make for an interesting comp though.', '2011-02-09 00:15:29.000000', NULL, 1),
(6307402, 934588, 127046, '<td valign="top">Getting some barrel distortion on the tower.</td>', 'Getting some barrel distortion on the tower.', '2011-02-09 00:16:17.000000', NULL, 1),
(6307406, 934427, 127046, '<td valign="top">I think a comp closer to the fence, to grab more of a sense of depth might have been better. Nice idea though.</td>', 'I think a comp closer to the fence, to grab more of a sense of depth might have been better. Nice idea though.', '2011-02-09 00:17:43.000000', NULL, 1),
(6307408, 933430, 127046, '<td valign="top">Very nice.</td>', 'Very nice.', '2011-02-09 00:18:12.000000', NULL, 1),
(6307414, 934537, 127046, '<td valign="top">A bit over processed for my tastes. Also, the dogs are pulling in different directions, one left, one right, two at the camera.</td>', 'A bit over processed for my tastes. Also, the dogs are pulling in different directions, one left, one right, two at the camera.', '2011-02-09 00:19:29.000000', NULL, 1),
(6307427, 933929, 127046, '<td valign="top">Personally, I like a lower perspective shot. Nice shot though.</td>', 'Personally, I like a lower perspective shot. Nice shot though.', '2011-02-09 00:21:24.000000', NULL, 1),
(6307449, 933939, 127046, '<td valign="top">The branch in the bottom right disrupts the line for me.</td>', 'The branch in the bottom right disrupts the line for me.', '2011-02-09 00:29:25.000000', NULL, 1),
(6307453, 933958, 127046, '<td valign="top">Slightly off center. If you are going for symmetry, you have to nail it. I would like to see this in a B&amp;W. Still, nice shot and idea.</td>', 'Slightly off center. If you are going for symmetry, you have to nail it. I would like to see this in a B&W. Still, nice shot and idea.', '2011-02-09 00:31:18.000000', NULL, 1),
(6307456, 934437, 127046, '<td valign="top">I think the bright pink detracts from the composition elements of the piece. Pretty model though and nice exposure.</td>', 'I think the bright pink detracts from the composition elements of the piece. Pretty model though and nice exposure.', '2011-02-09 00:33:44.000000', NULL, 1),
(6307457, 933852, 127046, '<td valign="top">Great symmetry and great use of B&amp;W.</td>', 'Great symmetry and great use of B&W.', '2011-02-09 00:34:08.000000', NULL, 1),
(6307465, 934300, 127046, '<td valign="top">Eh, is this just blue?</td>', 'Eh, is this just blue?', '2011-02-09 00:36:56.000000', NULL, 1),
(6307467, 934433, 127046, '<td valign="top">I like it, nice color correction (I''m assuming).</td>', 'I like it, nice color correction (I''m assuming).', '2011-02-09 00:37:21.000000', NULL, 1),
(6307470, 934087, 127046, '<td valign="top">Great job. I think the only thing I would change is a ceiling that isn''t textured.</td>', 'Great job. I think the only thing I would change is a ceiling that isn''t textured.', '2011-02-09 00:38:16.000000', NULL, 1),
(6307472, 933605, 83313, '<td valign="top">I love your idea of using the knife as a leading line. Unfortunately, there are some problems for me with this shot. I think the depth of field is way too shallow for the subject. I think the knife and at least most of the chicken should have been in focus. Also, the white balance is a bit too much on the yellow side. You also put some text on the image in the form of a copyright notice. That kills your anonymity in this challenge, but more importantly, your entry will get disqualified for the addition of text. Sorry.</td>', 'I love your idea of using the knife as a leading line. Unfortunately, there are some problems for me with this shot. I think the depth of field is way too shallow for the subject. I think the knife and at least most of the chicken should have been in focus. Also, the white balance is a bit too much on the yellow side. You also put some text on the image in the form of a copyright notice. That kills your anonymity in this challenge, but more importantly, your entry will get disqualified for the addition of text. Sorry.', '2011-02-09 00:38:59.000000', NULL, 1),
(6307496, 934381, 123833, '<td valign="top">Beautiful photo</td>', 'Beautiful photo', '2011-02-09 00:48:05.000000', NULL, 1),
(6307498, 933776, 123833, '<td valign="top">Something entirely different - I like it!</td>', 'Something entirely different - I like it!', '2011-02-09 00:48:37.000000', NULL, 1),
(6307504, 933736, 123833, '<td valign="top">Interesting</td>', 'Interesting', '2011-02-09 00:49:21.000000', NULL, 1),
(6307507, 934496, 123833, '<td valign="top">I really like it!</td>', 'I really like it!', '2011-02-09 00:49:53.000000', NULL, 1),
(6307510, 934566, 96751, '<td valign="top">I''m gonna guess <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=30214" rel="nofollow" target="_blank">LevT</a> :-)  And even if it isn''t, I''m gonna guess ribbon.  Been to this incredible place, and have a picture of me straddling the "stream".</td>', 'I''m gonna guess  LevT :-)  And even if it isn''t, I''m gonna guess ribbon.  Been to this incredible place, and have a picture of me straddling the "stream".', '2011-02-09 00:50:22.000000', NULL, 1),
(6307511, 934313, 123833, '<td valign="top">Very interesting</td>', 'Very interesting', '2011-02-09 00:51:12.000000', NULL, 1),
(6307512, 934437, 96751, '<td valign="top">The quality of this image is terrific.  I didn''t think the lines were particularly leading until I decided to follow them, and they led me to her hips.  So I guess, yeah, they are leading.</td>', 'The quality of this image is terrific.  I didn''t think the lines were particularly leading until I decided to follow them, and they led me to her hips.  So I guess, yeah, they are leading.', '2011-02-09 00:51:25.000000', NULL, 1),
(6307514, 934233, 123833, '<td valign="top">It looks like HDR, nice</td>', 'It looks like HDR, nice', '2011-02-09 00:51:31.000000', NULL, 1),
(6307516, 934421, 123833, '<td valign="top">Beautiful view</td>', 'Beautiful view', '2011-02-09 00:51:47.000000', NULL, 1),
(6307517, 934521, 123833, '<td valign="top">Very nice composition</td>', 'Very nice composition', '2011-02-09 00:52:03.000000', NULL, 1),
(6307518, 934395, 96751, '<td valign="top">This looks so beautiful, Wendy.  I didn''t notice the square shadows on the left before.  Beautifully pp''d.</td>', 'This looks so beautiful, Wendy.  I didn''t notice the square shadows on the left before.  Beautifully pp''d.', '2011-02-09 00:52:06.000000', NULL, 1),
(6307521, 934530, 96751, '<td valign="top">Beautiful image, and a wonderful find in the fence.  An inspired thought to place the tulips there.  I just wish the image was brighter, though.  There seems to be a general dullness.</td>', 'Beautiful image, and a wonderful find in the fence.  An inspired thought to place the tulips there.  I just wish the image was brighter, though.  There seems to be a general dullness.', '2011-02-09 00:53:03.000000', NULL, 1),
(6307525, 934371, 96751, '<td valign="top">Fabulous space.  And lots of lines.  But they don''t seem to be particularly "leading".</td>', 'Fabulous space.  And lots of lines.  But they don''t seem to be particularly "leading".', '2011-02-09 00:53:46.000000', NULL, 1),
(6307528, 934375, 96751, '<td valign="top">That face in the tree is SO unexpected.</td>', 'That face in the tree is SO unexpected.', '2011-02-09 00:54:12.000000', NULL, 1),
(6307530, 934173, 96751, '<td valign="top">A study in green.  Like it''s in Oz.</td>', 'A study in green.  Like it''s in Oz.', '2011-02-09 00:54:38.000000', NULL, 1),
(6307532, 934413, 96751, '<td valign="top">Hmmmmm.  I keep wanting this to be b/w.</td>', 'Hmmmmm.  I keep wanting this to be b/w.', '2011-02-09 00:55:07.000000', NULL, 1),
(6307533, 933915, 96751, '<td valign="top">Very clever use of aspirins.  Beautiful lighting.</td>', 'Very clever use of aspirins.  Beautiful lighting.', '2011-02-09 00:55:45.000000', NULL, 1),
(6307535, 934381, 96751, '<td valign="top">A view from the center of the merry-go-round.  Looking out.</td>', 'A view from the center of the merry-go-round.  Looking out.', '2011-02-09 00:56:23.000000', NULL, 1),
(6307537, 934069, 96751, '<td valign="top">Beautiful vista.</td>', 'Beautiful vista.', '2011-02-09 00:56:54.000000', NULL, 1),
(6307540, 934362, 96751, '<td valign="top">I can''t tell what I''m looking at near the bridge.  But the canal is definitely leading me to look at it.</td>', 'I can''t tell what I''m looking at near the bridge.  But the canal is definitely leading me to look at it.', '2011-02-09 00:57:53.000000', NULL, 1),
(6307542, 934287, 96751, '<td valign="top">I recognize this path.  It last led to a ribbon.</td>', 'I recognize this path.  It last led to a ribbon.', '2011-02-09 00:58:17.000000', NULL, 1),
(6307544, 934512, 96751, '<td valign="top">Incredible.  Also wonderful rule of thirds.</td>', 'Incredible.  Also wonderful rule of thirds.', '2011-02-09 00:58:58.000000', NULL, 1),
(6307545, 934433, 96751, '<td valign="top">That curve in the ground TOTALLY makes this shot spectacular.  Nicely seen and pp''d.</td>', 'That curve in the ground TOTALLY makes this shot spectacular.  Nicely seen and pp''d.', '2011-02-09 00:59:53.000000', NULL, 1),
(6307546, 933976, 96751, '<td valign="top">Very futuristic.</td>', 'Very futuristic.', '2011-02-09 01:00:17.000000', NULL, 1),
(6307547, 933444, 96751, '<td valign="top">Very interesting interpretation f the challenge.  We generally think of "leading lines" as straight or curved, but not branched and certainly not encased in ice.  Incredible.</td>', 'Very interesting interpretation f the challenge.  We generally think of "leading lines" as straight or curved, but not branched and certainly not encased in ice.  Incredible.', '2011-02-09 01:01:10.000000', NULL, 1),
(6307549, 934485, 96751, '<td valign="top">A road.  Perhaps there, or perhaps just wishful thinking from someone with a dream.</td>', 'A road.  Perhaps there, or perhaps just wishful thinking from someone with a dream.', '2011-02-09 01:02:10.000000', NULL, 1),
(6307550, 933631, 96751, '<td valign="top">Deb?  More Ventura?  Gorgeous light.  And lights.</td>', 'Deb?  More Ventura?  Gorgeous light.  And lights.', '2011-02-09 01:03:27.000000', NULL, 1),
(6307557, 933736, 96751, '<td valign="top">I think I recognize this patch of concrete.  Brian?  Like the leading lines got sneezed on by the Grain Master.</td>', 'I think I recognize this patch of concrete.  Brian?  Like the leading lines got sneezed on by the Grain Master.', '2011-02-09 01:06:05.000000', NULL, 1),
(6307562, 934262, 96751, '<td valign="top">Oh, the light is just glorious here.  I so want to follow those leading stairs.</td>', 'Oh, the light is just glorious here.  I so want to follow those leading stairs.', '2011-02-09 01:07:06.000000', NULL, 1),
(6307566, 934414, 96751, '<td valign="top">A shadow holding the key to the mystery.  I want to follow it and ask it the answer to the secret.</td>', 'A shadow holding the key to the mystery.  I want to follow it and ask it the answer to the secret.', '2011-02-09 01:08:36.000000', NULL, 1),
