(6307570, 934015, 96751, '<td valign="top">Terrific dof.</td>', 'Terrific dof.', '2011-02-09 01:09:33.000000', NULL, 1),
(6307572, 934217, 96751, '<td valign="top">A wonderful pattern and the lighting is also beautiful, but I think the lines are too fractured to actually seem like they''re "leading".</td>', 'A wonderful pattern and the lighting is also beautiful, but I think the lines are too fractured to actually seem like they''re "leading".', '2011-02-09 01:10:27.000000', NULL, 1),
(6307573, 934499, 96751, '<td valign="top">Love the double line of the bollards and the overhead lights.  Plus the terrific balance of the girl on one side and the pigeon on the other.  Unless it''s just some cruel anti-animal segregation rule.</td>', 'Love the double line of the bollards and the overhead lights.  Plus the terrific balance of the girl on one side and the pigeon on the other.  Unless it''s just some cruel anti-animal segregation rule.', '2011-02-09 01:11:12.000000', NULL, 1),
(6307575, 934509, 96751, '<td valign="top">The shine on the road made me sigh.</td>', 'The shine on the road made me sigh.', '2011-02-09 01:11:34.000000', NULL, 1),
(6307580, 934566, 123833, '<td valign="top">My top for this challenge (should it be Kahn, not Kohn?)</td>', 'My top for this challenge (should it be Kahn, not Kohn?)', '2011-02-09 01:15:40.000000', NULL, 1),
(6307581, 933389, 96751, '<td valign="top">I''m not yet well versed enough in style reading, but this looks like it might have <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=11769" rel="nofollow" target="_blank">jmritz</a>''s Grain Master touch.  I don''t know how you achieve this sort of pp''ing, but it always grabs me by the heart.</td>', 'I''m not yet well versed enough in style reading, but this looks like it might have  jmritz''s Grain Master touch.  I don''t know how you achieve this sort of pp''ing, but it always grabs me by the heart.', '2011-02-09 01:15:52.000000', NULL, 1),
(6307584, 934433, 114285, '<td valign="top">Oh wow, this is very good, lucky to find a place like this, love the curved grass.</td>', 'Oh wow, this is very good, lucky to find a place like this, love the curved grass.', '2011-02-09 01:16:17.000000', NULL, 1),
