(6307769, 934039, 51638, '<td valign="top">I''ll vote on this on the assumption it was done legally in basic editing, but I suspect you may have a bit of a DQ problem here.</td>', 'I''ll vote on this on the assumption it was done legally in basic editing, but I suspect you may have a bit of a DQ problem here.', '2011-02-09 06:21:07.000000', NULL, 1),
(6307770, 934328, 51638, '<td valign="top">Whilst there are certainly plenty of lines in this, I just don''t feel as though my eye is being drawn in any particular direction by them.</td>', 'Whilst there are certainly plenty of lines in this, I just don''t feel as though my eye is being drawn in any particular direction by them.', '2011-02-09 06:22:59.000000', NULL, 1),
(6307771, 934437, 51638, '<td valign="top">For this particular challenge I''d have placed your model further along the bridge. As it is, her placement is interrupting the lines created by the woodwork.</td>', 'For this particular challenge I''d have placed your model further along the bridge. As it is, her placement is interrupting the lines created by the woodwork.', '2011-02-09 06:26:09.000000', NULL, 1),
(6307772, 934262, 51638, '<td valign="top">If I had to be picky I''d say it could maybe do with a little more contrast. But a very nice image all the same.</td>', 'If I had to be picky I''d say it could maybe do with a little more contrast. But a very nice image all the same.', '2011-02-09 06:28:41.000000', NULL, 1),
(6307774, 934269, 51638, '<td valign="top">A nice image and perfect interpretation of the challenge topic, but to me spoiled a little by the very heavy handed PP.</td>', 'A nice image and perfect interpretation of the challenge topic, but to me spoiled a little by the very heavy handed PP.', '2011-02-09 06:29:59.000000', NULL, 1),
(6307775, 933631, 51638, '<td valign="top">Very nice. Exposure is spot on and a perfect example of leading lines. Front page? Maybe.</td>', 'Very nice. Exposure is spot on and a perfect example of leading lines. Front page? Maybe.', '2011-02-09 06:33:23.000000', NULL, 1),
(6307780, 934304, 51638, '<td valign="top">Not a big fan of the composition I''m afraid. Might have suited the challenge better if you''d been up higher looking more along the bridge. But hey, I wasn''t there, so maybe that wasn''t possible or didn''t look as good as this.</td>', 'Not a big fan of the composition I''m afraid. Might have suited the challenge better if you''d been up higher looking more along the bridge. But hey, I wasn''t there, so maybe that wasn''t possible or didn''t look as good as this.', '2011-02-09 06:35:46.000000', NULL, 1),
(6307782, 933852, 51638, '<td valign="top">Yup, works for me.</td>', 'Yup, works for me.', '2011-02-09 06:36:31.000000', NULL, 1),
(6307784, 933824, 86359, '<td valign="top">I finally found the yellow bird! You should instate a prize for this...</td>', 'I finally found the yellow bird! You should instate a prize for this...', '2011-02-09 06:38:01.000000', NULL, 1),
(6307785, 934233, 51638, '<td valign="top">Nice use of HDR.</td>', 'Nice use of HDR.', '2011-02-09 06:38:17.000000', NULL, 1),
(6307786, 934371, 51638, '<td valign="top">Terrific. The addition of the person really adds to the shot.</td>', 'Terrific. The addition of the person really adds to the shot.', '2011-02-09 06:39:00.000000', NULL, 1),
(6307791, 934015, 51638, '<td valign="top">That is one shallow DOF! In fact, just a little too shallow for me to feel as as though my gaze is beind drawn in to the lines. I find myself staring at the very small in focus spot in the middle of the image.</td>', 'That is one shallow DOF! In fact, just a little too shallow for me to feel as as though my gaze is beind drawn in to the lines. I find myself staring at the very small in focus spot in the middle of the image.', '2011-02-09 06:42:38.000000', NULL, 1),
(6307792, 934007, 51638, '<td valign="top">I''d like to have this composed so the sign wasn''t visible. As it is I find my gaze just drawn to the sign, rather than along the lines created by the fences.</td>', 'I''d like to have this composed so the sign wasn''t visible. As it is I find my gaze just drawn to the sign, rather than along the lines created by the fences.', '2011-02-09 06:44:23.000000', NULL, 1),
(6307798, 934116, 51638, '<td valign="top">Nice shot, with an obviously long shutter speed which has shown up a number of hot pixels. You could have cloned these, which would have improved it that little bit more. But still worthy of a good score.</td>', 'Nice shot, with an obviously long shutter speed which has shown up a number of hot pixels. You could have cloned these, which would have improved it that little bit more. But still worthy of a good score.', '2011-02-09 06:50:05.000000', NULL, 1),
(6307801, 934217, 51638, '<td valign="top">Very cool lines and lighting.</td>', 'Very cool lines and lighting.', '2011-02-09 06:52:02.000000', NULL, 1),
(6307806, 934337, 51638, '<td valign="top">Nice work. Great take on the challenge.</td>', 'Nice work. Great take on the challenge.', '2011-02-09 06:54:46.000000', NULL, 1),
(6307810, 933986, 111483, '<td valign="top">this is very pretty very sharp very nice,i love the beach</td>', 'this is very pretty very sharp very nice,i love the beach', '2011-02-09 07:09:15.000000', NULL, 1),
(6307867, 934542, 16148, '<td valign="top">This is a beautiful photograph except for the over exposed sky.  Reminds me of an Andrew Wyeth painting.  Your composition, textures, story, and sepia tones are perfect.</td>', 'This is a beautiful photograph except for the over exposed sky.  Reminds me of an Andrew Wyeth painting.  Your composition, textures, story, and sepia tones are perfect.', '2011-02-09 08:39:23.000000', NULL, 1),
