(6313637, 933814, 91342, '<td valign="top">Nice image.  Think I might like it a bit if the camera was an inch or two more to the right.</td>', 'Nice image.  Think I might like it a bit if the camera was an inch or two more to the right.', '2011-02-14 18:15:01.000000', NULL, 1),
(6313639, 934381, 91342, '<td valign="top">Very nice image.  Especially like the ghost motion impact.</td>', 'Very nice image.  Especially like the ghost motion impact.', '2011-02-14 18:15:46.000000', NULL, 1),
(6313640, 933444, 67258, '<td valign="top">Clever use of leading lines.</td>', 'Clever use of leading lines.', '2011-02-14 18:16:15.000000', NULL, 1),
(6313641, 934588, 91342, '<td valign="top">Pretty shot.  Not sure I consider it leading lines since the bridge leads to distant blah hills.  Not much you could have done different in basic editing.</td>', 'Pretty shot.  Not sure I consider it leading lines since the bridge leads to distant blah hills.  Not much you could have done different in basic editing.', '2011-02-14 18:17:11.000000', NULL, 1),
(6313642, 934522, 91342, '<td valign="top">Effective use of lines leading to bridge</td>', 'Effective use of lines leading to bridge', '2011-02-14 18:17:29.000000', NULL, 1),
(6313644, 934249, 91342, '<td valign="top">Like the shot very much, just not sure if it uses leading lines to something.  More like framing lines.</td>', 'Like the shot very much, just not sure if it uses leading lines to something.  More like framing lines.', '2011-02-14 18:18:23.000000', NULL, 1),
(6313645, 933976, 91342, '<td valign="top">White bench on left is confusing.  Nice leading line to the structure above.</td>', 'White bench on left is confusing.  Nice leading line to the structure above.', '2011-02-14 18:19:19.000000', NULL, 1),
(6313646, 934496, 91342, '<td valign="top">Effective lines leading to the subject.  Wondering if b/w rather than sepia would be more pleasing.</td>', 'Effective lines leading to the subject.  Wondering if b/w rather than sepia would be more pleasing.', '2011-02-14 18:20:15.000000', NULL, 1),
(6313647, 934323, 91342, '<td valign="top">Very nice idea.  Just wondering if it would be better for western viewers if flipped so arrow goes left to right.  However, as a lefty I like it this way.</td>', 'Very nice idea.  Just wondering if it would be better for western viewers if flipped so arrow goes left to right.  However, as a lefty I like it this way.', '2011-02-14 18:21:40.000000', NULL, 1),
(6313649, 934138, 91342, '<td valign="top">just a bit dark for my taste</td>', 'just a bit dark for my taste', '2011-02-14 18:22:04.000000', NULL, 1),
(6313653, 934371, 91342, '<td valign="top">Very nice, the title is great play on words.  my favorite so far</td>', 'Very nice, the title is great play on words.  my favorite so far', '2011-02-14 18:23:06.000000', NULL, 1),
(6313655, 934269, 91342, '<td valign="top">I''m drawn to the center line leading to distant object.  Is that more trees?</td>', 'I''m drawn to the center line leading to distant object.  Is that more trees?', '2011-02-14 18:24:05.000000', NULL, 1),
(6313657, 933696, 91342, '<td valign="top">lines lead effectively to the person</td>', 'lines lead effectively to the person', '2011-02-14 18:25:01.000000', NULL, 1),
(6313659, 934537, 91342, '<td valign="top">Very nice idea.  How did you get the effect?  My dogs are feeling those leading lines.</td>', 'Very nice idea.  How did you get the effect?  My dogs are feeling those leading lines.', '2011-02-14 18:26:28.000000', NULL, 1),
