(6319152, 934566, 15711, '<td valign="top">WOW - that''s pretty fantastic.  The perfect example of the term.  Congrats.</td>', 'WOW - that''s pretty fantastic.  The perfect example of the term.  Congrats.', '2011-02-17 20:03:16.000000', NULL, 0),
(6319352, 933929, 126371, '<td valign="top">Good shot. IMO, I''d like to see more at the top (more of the tree at top right)? This has a great mood to it...</td>', 'Good shot. IMO, I''d like to see more at the top (more of the tree at top right)? This has a great mood to it...', '2011-02-17 22:51:20.000000', NULL, 0),
(6319354, 934269, 126371, '<td valign="top">Really nice photo. I like the mood this has---don''t see stuff like this much. Great composition and editing! Also, the pigeons add a lot...</td>', 'Really nice photo. I like the mood this has---don''t see stuff like this much. Great composition and editing! Also, the pigeons add a lot...', '2011-02-17 22:54:05.000000', NULL, 0),
(6319356, 934496, 126371, '<td valign="top">Nice shot! This definitely caught my attention here in this challenge. I do agree that it would be neat if it were sharper and the white spot was toned down a bit... IMO, the composition is perfect.</td>', 'Nice shot! This definitely caught my attention here in this challenge. I do agree that it would be neat if it were sharper and the white spot was toned down a bit... IMO, the composition is perfect.', '2011-02-17 22:58:14.000000', NULL, 0),
(6319643, 933736, 54645, '<td valign="top">I see a skull. Hovering in line.</td>', 'I see a skull. Hovering in line.', '2011-02-18 04:00:23.000000', NULL, 0),
(6319644, 933389, 54645, '<td valign="top">This put a smile on my face. It''s like you have cirrhosis and your long lost love has come to give you a liver...or maybe just a hug goodbye.</td>', 'This put a smile on my face. It''s like you have cirrhosis and your long lost love has come to give you a liver...or maybe just a hug goodbye.', '2011-02-18 04:02:11.000000', NULL, 0),
(6319645, 934537, 54645, '<td valign="top">What a joyful image...and I thought the lines led to the dogs.</td>', 'What a joyful image...and I thought the lines led to the dogs.', '2011-02-18 04:05:00.000000', NULL, 0),
(6319672, 934103, 77653, '<td valign="top">Kúl mynd!</td>', 'Kúl mynd!', '2011-02-18 06:48:41.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6319773, 933631, 100393, '<td valign="top">Very nicely made.</td>', 'Very nicely made.', '2011-02-18 10:28:44.000000', NULL, 0),
(6320166, 934566, 100393, '<td valign="top">Wow, beautifully done. Well done Lev.</td>', 'Wow, beautifully done. Well done Lev.', '2011-02-18 18:46:38.000000', NULL, 0),
(6320167, 934233, 100393, '<td valign="top">Very nicely made.</td>', 'Very nicely made.', '2011-02-18 18:47:16.000000', NULL, 0),
(6320168, 934103, 100393, '<td valign="top">This works really well. Well done.</td>', 'This works really well. Well done.', '2011-02-18 18:48:02.000000', NULL, 0),
(6320248, 934233, 4793, '<td valign="top">Beautiful, congratulations</td>', 'Beautiful, congratulations', '2011-02-18 20:17:41.000000', NULL, 0),
(6320249, 934103, 4793, '<td valign="top">Nice work</td>', 'Nice work', '2011-02-18 20:18:29.000000', NULL, 0),
(6320420, 933389, 58137, '<td valign="top">It reminds me of the work of the great modern artist and poet, Jason Steele (of Charlie the Unicorn fame):<br/> <br/>"I love the feel of grain, the screams of a man in pain, blood when it falls like rain, showering me."</td>', 'It reminds me of the work of the great modern artist and poet, Jason Steele (of Charlie the Unicorn fame): "I love the feel of grain, the screams of a man in pain, blood when it falls like rain, showering me."', '2011-02-19 00:47:05.000000', NULL, 0),
(6320932, 934233, 74559, '<td valign="top">This is quite lovely, I admire your processing as well!</td>', 'This is quite lovely, I admire your processing as well!', '2011-02-19 14:45:08.000000', NULL, 0),
(6321301, 934584, 117474, '<td valign="top">Leading lines are things that should support an interesting subject to enhance it somehow. Unfortunately I don''t see the leading lines here supporting in that way. I think that would have contributed significantly to the sub-5 score (by the way you really thrashed me in this challenge--my image didn''t even have leading lines!). <br/>Lines are a great way to feel the depth of an image, and your image really does go on for a long way. But I don''t know if depth by itself is enough. A subject, a something, a thing in there (someone walking with a clipboard even?) would have (in my opinion) helped the composition of the image.<br/>I like the location of your vanishing point. <br/>I think the white balance is a little too orange. Some adjustment would have helped (in my opinion). <br/>The reflections on the floor add another nice leading line. <br/>I like the grittyness on the wall on the left and wouldn''t have minded seeing more.</td>', 'Leading lines are things that should support an interesting subject to enhance it somehow. Unfortunately I don''t see the leading lines here supporting in that way. I think that would have contributed significantly to the sub-5 score (by the way you really thrashed me in this challenge--my image didn''t even have leading lines!). Lines are a great way to feel the depth of an image, and your image really does go on for a long way. But I don''t know if depth by itself is enough. A subject, a something, a thing in there (someone walking with a clipboard even?) would have (in my opinion) helped the composition of the image.I like the location of your vanishing point. I think the white balance is a little too orange. Some adjustment would have helped (in my opinion). The reflections on the floor add another nice leading line. I like the grittyness on the wall on the left and wouldn''t have minded seeing more.', '2011-02-19 20:14:00.000000', NULL, 0),
(6321490, 934231, 116253, '<td valign="top">Looks like you nailed this one!</td>', 'Looks like you nailed this one!', '2011-02-19 22:07:28.000000', NULL, 0),
(6321495, 934584, 116253, '<td valign="top">Very industrial, but I like it. Good lighting for the complete length of the hall. Not overly sharp but for any one that has worked there life in such an environment, everything becomes a blur after a while.</td>', 'Very industrial, but I like it. Good lighting for the complete length of the hall. Not overly sharp but for any one that has worked there life in such an environment, everything becomes a blur after a while.', '2011-02-19 22:17:24.000000', NULL, 0),
(6321661, 934233, 2110, '<td valign="top">brilliant!!<br/>topaz makes it look magical!</td>', 'brilliant!!topaz makes it look magical!', '2011-02-20 01:27:59.000000', NULL, 0),
(6321851, 934566, 68020, '<td valign="top">Congrats on the ribbon and the 1x....awesome capture!</td>', 'Congrats on the ribbon and the 1x....awesome capture!', '2011-02-20 09:07:13.000000', NULL, 0),
(6323028, 934584, 66641, '<td valign="top">Thanks for the comments!  NiallOT - you''re right about everything.  I kept thinking to myself after the challenge, "why couldn''t I see that I had to have an interesting subject??  Just lines aren''t enough, you dummy!" ha<br/> <br/>The sharpness - I don''t know what happened, it was sharp on my computer, and when I uploaded to the site, it came out completely different.  That irritated me a lot.  <br/> <br/>Any other editing - I have no idea what I''m doing!  Just downloaded free editing software a couple weeks ago (3 weeks maybe?) and I''ve just been tinkering around and slowly learning.  Yeah, the orange is a bit much.  Wish I had known how to fix that.</td>', 'Thanks for the comments!  NiallOT - you''re right about everything.  I kept thinking to myself after the challenge, "why couldn''t I see that I had to have an interesting subject??  Just lines aren''t enough, you dummy!" ha The sharpness - I don''t know what happened, it was sharp on my computer, and when I uploaded to the site, it came out completely different.  That irritated me a lot.   Any other editing - I have no idea what I''m doing!  Just downloaded free editing software a couple weeks ago (3 weeks maybe?) and I''ve just been tinkering around and slowly learning.  Yeah, the orange is a bit much.  Wish I had known how to fix that.', '2011-02-20 21:19:04.000000', NULL, 0),
(6323085, 934233, 48560, '<td valign="top">maybe its the processing/smoothening... it looks like a scene from a video game!</td>', 'maybe its the processing/smoothening... it looks like a scene from a video game!', '2011-02-20 21:44:09.000000', NULL, 0),
(6324633, 933430, 96751, '<td valign="top">Congrats on your first entry.  You did exceptionally well (look at the average from commenters!), and scoring a blue PH ribbon in the process.  Those in the know are very envious :-)<br/> <br/>Welcome, and looking forward to more work from you.</td>', 'Congrats on your first entry.  You did exceptionally well (look at the average from commenters!), and scoring a blue PH ribbon in the process.  Those in the know are very envious :-) Welcome, and looking forward to more work from you.', '2011-02-21 11:54:31.000000', NULL, 0),
(6326160, 934566, 8891, '<td valign="top">Superb perspective and great golden tones leading the eye to that long figure. Great job, Lev! Congrats on your new blue!</td>', 'Superb perspective and great golden tones leading the eye to that long figure. Great job, Lev! Congrats on your new blue!', '2011-02-22 06:02:04.000000', NULL, 0),
(6328477, 934530, 8367, '<td valign="top">Congratulations on your high finish and pb.  Great capture!</td>', 'Congratulations on your high finish and pb.  Great capture!', '2011-02-23 09:33:44.000000', NULL, 0),
(6328714, 933389, 30861, '<td valign="top">You''re certainly producing work of a certain <i>gravitas</i>, friend, even when it''s a beaming, good-humored gravitas. We have GOT to get together soon, OK?</td>', 'You''re certainly producing work of a certain gravitas, friend, even when it''s a beaming, good-humored gravitas. We have GOT to get together soon, OK?', '2011-02-23 11:35:24.000000', NULL, 0),
(6333113, 934173, 121692, '<td valign="top">Sorry about the delay in answering, this is just a simple plant that grows here on the ranch. I took the shot so that it was laying horizontal. Thanks for the comments, they really do help. :)</td>', 'Sorry about the delay in answering, this is just a simple plant that grows here on the ranch. I took the shot so that it was laying horizontal. Thanks for the comments, they really do help. :)', '2011-02-26 15:30:39.000000', NULL, 0),
